python3 -c "
import json
with open('/home/runner/.templateengine/dotnetcli/11.0.100-preview.3.26207.106/templatecache.json') as f:
    data = json.load(f)
print('Keys:', list(data.keys())[:5])
if 'TemplatePackages' in data:
    pkgs = data['TemplatePackages']
    print(f'Template packages: {len(pkgs)}')
    for pkg in pkgs:
        mp = pkg.get('MountPointUri', '') or str(pkg.get('InstallPath', ''))
        if 'MyTests' in mp or 'team-test' in str(pkg):
            print(f'  {mp}')
elif 'TemplateInfo' in data:
    for t in data['TemplateInfo']:
        if 'team' in str(t).lower():
            print(t.get('Identity', ''), t.get('MountPointUri', ''))
else:
    # Just show structure
    for k in data:
        print(f'{k}: {type(data[k]).__name__} len={len(data[k]) if hasattr(data[k], \"__len__\") else \"N/A\"}')
" 2>&1

